/* The C structs generated by procctl-gen must encode the samples to exactly
 * the golden vectors (which the Go codec is also tested against). */
#include "../gen/testproto_schema.h"

#include <stdio.h>
#include <stdlib.h>

static int check(const char *path, const void *want, size_t n) {
  unsigned char buf[4096];
  FILE *f = fopen(path, "rb");
  if (!f) { perror(path); return 1; }
  size_t got = fread(buf, 1, sizeof buf, f);
  fclose(f);
  if (got != n || memcmp(buf, want, n) != 0) {
    fprintf(stderr, "%s: C encoding differs (%zu vs %zu bytes)\n", path, n, got);
    return 1;
  }
  printf("ok %s\n", path);
  return 0;
}

int main(int argc, char **argv) {
  const char *dir = argc > 1 ? argv[1] : "testdata/vectors";
  char p[512];
  testproto_agent_t a;
  testproto_status_t s;
  testproto_agent_sample(&a);
  testproto_status_sample(&s);
  int bad = 0;
  snprintf(p, sizeof p, "%s/testproto_agent.bin", dir);
  bad |= check(p, &a, sizeof a);
  snprintf(p, sizeof p, "%s/testproto_status.bin", dir);
  bad |= check(p, &s, sizeof s);
  return bad;
}
